  padding: 1rem;
}

.field {
  margin-bottom: 1rem;
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

input[type="number"],
input[type="text"],
select {
  width: 100%;
  padding: 0.5rem;
  border: 1px solid var(--border);
  border-radius: 0.375rem;
  background: var(--bg);
  color: var(--fg);
  font-size: 1rem;
}

.hint {
  color: var(--muted);
  font-size: 0.875rem;
  margin-top: 0.25rem;
}

button {
  background: var(--accent);
  color: var(--accent-contrast);
  border: none;
  border-radius: 0.375rem;
  padding: 0.6rem 1.2rem;
  font-size: 1rem;
  cursor: pointer;
}

button:hover {
  filter: brightness(1.1);
}

button.secondary {
  background: transparent;
  color: var(--accent);
  border: 1px solid var(--accent);
  margin-left: 0.5rem;
}

button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--accent) 45%, transparent);
  outline-offset: 2px;
}

#errors {
  background: var(--error-bg);
  color: var(--error-fg);
  border-radius: 0.375rem;
  padding: 0.75rem 1rem;
  margin: 1rem 0;
}

.results-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));
  gap: 1rem;
  margin: 1rem 0;
}

.results-grid dt {
  font-size: 0.875rem;
  color: var(--muted);
}

.results-grid dd {
  font-size: 1.4rem;
  font-weight: 700;
  margin: 0;
}

.note {
  color: var(--muted);
  font-size: 0.875rem;
}

#policy-text,
#deposit-policy-text {
  width: 100%;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  padding: 0.75rem;
  border: 1px solid var(--border);
  border-radius: 0.375rem;
  background: var(--bg);
  color: var(--fg);
}

#copy-status {
  margin-left: 0.75rem;
  color: var(--muted);
}

.table-wrap { overflow-x: auto; }

table { border-collapse: collapse; width: 100%; min-width: 36rem; }

th, td { border-bottom: 1px solid var(--border); padding: 0.65rem 0.5rem; text-align: left; }

thead th { color: var(--muted); font-size: 0.875rem; }

.selected-scenario { background: color-mix(in srgb, var(--accent) 12%, var(--bg)); }

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}

section {
  margin-bottom: 2.5rem;
}

footer {
  border-top: 1px solid var(--border);
  padding-top: 1rem;
  color: var(--muted);
  font-size: 0.875rem;
}

